-- Unified Database Initialization Migration V1__init.sql

CREATE TABLE IF NOT EXISTS "users" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "username" TEXT NOT NULL,
    "email" VARCHAR(255) NOT NULL UNIQUE,
    "password" TEXT NOT NULL,
    "role" VARCHAR(25) NOT NULL DEFAULT 'SELLER',
    "status" VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
    "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "category" (
    "id" SMALLINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name" VARCHAR(50) NOT NULL,
    PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "product" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" BIGINT NOT NULL,
    "category_id" SMALLINT,
    "name" VARCHAR(100) NOT NULL,
    "description" TEXT NOT NULL,
    "price" DECIMAL(10,2) NOT NULL,
    "original_price" NUMERIC(10, 2),
    "discount_rate" INTEGER,
    "quantity" BIGINT NOT NULL DEFAULT 0,
    "is_pack" BOOLEAN NOT NULL DEFAULT FALSE,
    "is_listed" BOOLEAN NOT NULL DEFAULT TRUE,
    "thumbnail_url" TEXT,
    "hover_image_url" TEXT,
    "video_url" TEXT,
    PRIMARY KEY("id"),
    CONSTRAINT "fk_product_user" FOREIGN KEY("user_id") REFERENCES "users"("id") ON DELETE CASCADE,
    CONSTRAINT "fk_product_category" FOREIGN KEY("category_id") REFERENCES "category"("id") ON DELETE SET NULL
);

CREATE TABLE IF NOT EXISTS "product_images" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "product_id" BIGINT NOT NULL,
    "image_url" TEXT NOT NULL,
    PRIMARY KEY("id"),
    CONSTRAINT "fk_product_images_product" FOREIGN KEY ("product_id") REFERENCES "product"("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "cart" (
    "id" UUID NOT NULL,
    "user_id" BIGINT,
    "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY("id"),
    CONSTRAINT "fk_cart_user" FOREIGN KEY("user_id") REFERENCES "users"("id") ON DELETE SET NULL
);

CREATE TABLE IF NOT EXISTS "cart_item" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "cart_id" UUID NOT NULL,
    "product_id" BIGINT NOT NULL,
    "quantity" BIGINT NOT NULL DEFAULT 1,
    PRIMARY KEY("id"),
    CONSTRAINT "fk_cart_item_cart" FOREIGN KEY("cart_id") REFERENCES "cart"("id") ON DELETE CASCADE,
    CONSTRAINT "fk_cart_item_product" FOREIGN KEY("product_id") REFERENCES "product"("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "order" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "guest_name" VARCHAR(100) NOT NULL,
    "phone_number" VARCHAR(30) NOT NULL,
    "shipping_address" TEXT NOT NULL,
    "city" VARCHAR(100) NOT NULL,
    "guest_email" VARCHAR(255),
    "total_price" DECIMAL(10,2) NOT NULL,
    "status" VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "order_items" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "order_id" BIGINT NOT NULL,
    "product_id" BIGINT,
    "seller_id" BIGINT NOT NULL,
    "quantity" BIGINT NOT NULL,
    "price" DECIMAL(10,2) NOT NULL,
    PRIMARY KEY("id"),
    CONSTRAINT "fk_order_items_order" FOREIGN KEY("order_id") REFERENCES "order"("id") ON DELETE CASCADE,
    CONSTRAINT "fk_order_items_product" FOREIGN KEY("product_id") REFERENCES "product"("id") ON DELETE SET NULL,
    CONSTRAINT "fk_order_items_seller" FOREIGN KEY("seller_id") REFERENCES "users"("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "feedback" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "product_id" BIGINT,
    "seller_id" BIGINT,
    "customer_name" VARCHAR(100) NOT NULL,
    "comment" TEXT NOT NULL,
    "rating" SMALLINT NOT NULL DEFAULT 5,
    "is_visible" BOOLEAN NOT NULL DEFAULT TRUE,
    "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY("id"),
    CONSTRAINT "fk_feedback_product" FOREIGN KEY("product_id") REFERENCES "product"("id") ON DELETE CASCADE,
    CONSTRAINT "fk_feedback_seller" FOREIGN KEY("seller_id") REFERENCES "users"("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "store_settings" (
    "id" BIGINT NOT NULL PRIMARY KEY DEFAULT 1,
    "phone" VARCHAR(100),
    "email" VARCHAR(255),
    "timing" TEXT,
    "address" TEXT,
    "hero_eyebrow" TEXT,
    "hero_title" TEXT,
    "hero_intro" TEXT,
    "hero_cta" TEXT,
    "story1_eyebrow" TEXT,
    "story1_title" TEXT,
    "story1_intro" TEXT,
    "story1_cta" TEXT,
    "story1_image" TEXT,
    "story1_product_id" BIGINT,
    "story2_eyebrow" TEXT,
    "story2_title" TEXT,
    "story2_intro" TEXT,
    "story2_cta" TEXT,
    "story2_image" TEXT,
    "story2_product_id" BIGINT,
    "category_overrides" TEXT,
    "section_overrides" TEXT,
    "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

